ALTER TABLE public.site_settings ADD COLUMN retail_minimum_enabled boolean NOT NULL DEFAULT true, ADD COLUMN retail_minimum_amount numeric NOT NULL DEFAULT 3000 CHECK(retail_minimum_amount >= 0);
CREATE TABLE public.checkout_settings(id integer PRIMARY KEY DEFAULT 1 CHECK(id=1), test_mode boolean NOT NULL DEFAULT true, yookassa_enabled boolean NOT NULL DEFAULT true, invoice_enabled boolean NOT NULL DEFAULT true, yookassa_shop_id text, bank_details text, retail_delivery jsonb NOT NULL DEFAULT '["cdek","ozon","post"]'::jsonb, wholesale_delivery jsonb NOT NULL DEFAULT '["pek","kit"]'::jsonb, payment_secret_name text, delivery_secret_names jsonb NOT NULL DEFAULT '{}'::jsonb, created_subject text NOT NULL DEFAULT 'Заказ {number} — НеСдует', created_body text NOT NULL DEFAULT 'Спасибо за заказ {number}. Сумма: {total} ₽. Статус: {status}.', status_subject text NOT NULL DEFAULT 'Заказ {number}: {status}', status_body text NOT NULL DEFAULT 'Статус заказа {number} изменён: {status}.');
GRANT SELECT,INSERT,UPDATE,DELETE ON public.checkout_settings TO authenticated; GRANT ALL ON public.checkout_settings TO service_role;
ALTER TABLE public.checkout_settings ENABLE ROW LEVEL SECURITY;
CREATE POLICY checkout_settings_admin ON public.checkout_settings FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.orders(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),number bigint GENERATED ALWAYS AS IDENTITY, user_id uuid, created_at timestamptz NOT NULL DEFAULT now(), status text NOT NULL DEFAULT 'new' CHECK(status IN ('new','awaiting_payment','awaiting_delivery','paid','assembled','shipped','delivered','cancelled')), customer jsonb NOT NULL, buyer_type text NOT NULL CHECK(buyer_type IN ('person','organization')), is_dealer boolean NOT NULL DEFAULT false, delivery_method text NOT NULL, payment_method text NOT NULL, delivery_cost numeric, total numeric NOT NULL CHECK(total>=0), weight_g numeric, test_mode boolean NOT NULL DEFAULT true, consent boolean NOT NULL CHECK(consent), tracking_number text, admin_note text, receipt_url text CHECK(receipt_url IS NULL OR receipt_url ~ '^https://'));
GRANT SELECT,UPDATE ON public.orders TO authenticated; GRANT ALL ON public.orders TO service_role; GRANT USAGE,SELECT ON SEQUENCE public.orders_number_seq TO service_role;
ALTER TABLE public.orders ENABLE ROW LEVEL SECURITY;
CREATE POLICY orders_admin ON public.orders FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE POLICY orders_owner_read ON public.orders FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE TABLE public.order_items(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),order_id uuid NOT NULL REFERENCES public.orders(id) ON DELETE CASCADE,variant_id uuid NOT NULL,name text NOT NULL,volume_ml numeric,weight_g numeric,sku text,quantity integer NOT NULL CHECK(quantity>0),unit_price numeric NOT NULL CHECK(unit_price>=0),gross_weight_g numeric);
GRANT SELECT ON public.order_items TO authenticated; GRANT ALL ON public.order_items TO service_role;
ALTER TABLE public.order_items ENABLE ROW LEVEL SECURITY;
CREATE POLICY order_items_admin ON public.order_items FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin'));
CREATE POLICY order_items_owner ON public.order_items FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.orders WHERE id=order_id AND user_id=auth.uid()));
CREATE TABLE public.order_item_private(item_id uuid PRIMARY KEY REFERENCES public.order_items(id) ON DELETE CASCADE,cost_price numeric, tax_percent numeric NOT NULL, actual_margin_percent numeric);
GRANT SELECT ON public.order_item_private TO authenticated; GRANT ALL ON public.order_item_private TO service_role;
ALTER TABLE public.order_item_private ENABLE ROW LEVEL SECURITY;
CREATE POLICY order_private_admin ON public.order_item_private FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin'));
CREATE OR REPLACE FUNCTION public.checkout_options() RETURNS jsonb LANGUAGE sql SECURITY DEFINER SET search_path=public AS $$ SELECT jsonb_build_object('test_mode',c.test_mode,'yookassa',c.yookassa_enabled AND c.test_mode,'invoice',c.invoice_enabled,'retail_delivery',c.retail_delivery,'wholesale_delivery',c.wholesale_delivery,'minimum_enabled',s.retail_minimum_enabled,'minimum_amount',s.retail_minimum_amount,'shipping_city',s.shipping_city) FROM public.checkout_settings c CROSS JOIN public.site_settings s WHERE c.id=1 AND s.id=1 $$;
REVOKE ALL ON FUNCTION public.checkout_options() FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.checkout_options() TO anon,authenticated;
CREATE OR REPLACE FUNCTION public.cart_quote(_items jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE item jsonb; v record; q jsonb; dealer boolean; result jsonb:='[]'::jsonb; total numeric:=0; weight numeric:=0; missing_weight boolean:=false; amount numeric; enabled boolean; BEGIN IF jsonb_typeof(_items)<>'array' OR jsonb_array_length(_items)<1 OR jsonb_array_length(_items)>100 THEN RAISE EXCEPTION 'Корзина пуста или слишком велика'; END IF; IF EXISTS(SELECT 1 FROM jsonb_array_elements(_items) e GROUP BY e->>'variant_id' HAVING count(*)>1) THEN RAISE EXCEPTION 'Повтор фасовки'; END IF; SELECT EXISTS(SELECT 1 FROM public.dealer_accounts d JOIN public.wholesale_leads l ON l.id=d.lead_id WHERE d.user_id=auth.uid() AND d.approved AND l.status='approved') INTO dealer; FOR item IN SELECT * FROM jsonb_array_elements(_items) LOOP IF (item->>'quantity')::integer NOT BETWEEN 1 AND 1000000 THEN RAISE EXCEPTION 'Некорректное количество'; END IF; SELECT pv.*,p.name,p.slug,p.status INTO v FROM public.product_variants pv JOIN public.products p ON p.id=pv.product_id WHERE pv.id=(item->>'variant_id')::uuid; IF NOT FOUND OR v.status<>'published' OR NOT v.sold_on_site OR v.price IS NULL THEN RAISE EXCEPTION 'Фасовка недоступна для заказа'; END IF; IF v.stock IS NOT NULL AND v.stock < (item->>'quantity')::integer THEN RAISE EXCEPTION 'Недостаточный остаток'; END IF; IF dealer THEN q:=public.dealer_quote(v.id,(item->>'quantity')::integer); ELSE q:=jsonb_build_object('price',v.price); END IF; IF q IS NULL THEN RAISE EXCEPTION 'Цена не задана'; END IF; total:=total+(q->>'price')::numeric*(item->>'quantity')::integer; IF v.gross_weight_g IS NULL THEN missing_weight:=true; ELSE weight:=weight+v.gross_weight_g*(item->>'quantity')::integer; END IF; result:=result||jsonb_build_array(jsonb_build_object('variant_id',v.id,'product_id',v.product_id,'name',v.name,'slug',v.slug,'volume_ml',v.volume_ml,'weight_g',v.weight_g,'sku',v.sku,'quantity',(item->>'quantity')::integer,'price',(q->>'price')::numeric,'retail_price',v.price,'gross_weight_g',v.gross_weight_g)); END LOOP; SELECT retail_minimum_amount,retail_minimum_enabled INTO amount,enabled FROM public.site_settings WHERE id=1; RETURN jsonb_build_object('items',result,'total',total,'is_dealer',dealer,'weight_g',CASE WHEN missing_weight THEN NULL ELSE weight END,'shortfall',CASE WHEN NOT dealer AND enabled THEN greatest(amount-total,0) ELSE 0 END); END $$;
REVOKE ALL ON FUNCTION public.cart_quote(jsonb) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.cart_quote(jsonb) TO anon,authenticated;
CREATE OR REPLACE FUNCTION public.place_order(_items jsonb,_customer jsonb,_buyer_type text,_delivery text,_payment text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE quote jsonb; config public.checkout_settings; oid uuid; ono bigint; item jsonb; iid uuid; cost numeric; tax numeric; chosen_status text; BEGIN IF _buyer_type NOT IN ('person','organization') OR length(_customer->>'name') NOT BETWEEN 2 AND 200 OR coalesce(_customer->>'phone','') !~ '^[+0-9][0-9 ()-]{4,39}$' OR coalesce(_customer->>'email','') !~ '^[^ @]+@[^ @]+\.[^ @]+$' OR length(_customer->>'email')>254 OR coalesce(length(_customer->>'city'),0) NOT BETWEEN 1 AND 120 OR coalesce(length(_customer->>'address'),0) NOT BETWEEN 2 AND 500 OR coalesce(length(_customer->>'comment'),0)>3000 OR _customer->>'consent' IS DISTINCT FROM 'true' THEN RAISE EXCEPTION 'Проверьте контактные данные и согласие'; END IF; IF _buyer_type='organization' AND (coalesce(length(_customer->>'company'),0) NOT BETWEEN 2 AND 200 OR coalesce(_customer->>'inn','') !~ '^([0-9]{10}|[0-9]{12})$' OR (coalesce(_customer->>'kpp','')<>'' AND _customer->>'kpp' !~ '^[0-9]{9}$')) THEN RAISE EXCEPTION 'Проверьте реквизиты организации'; END IF; IF coalesce(_customer->>'messenger_type','') NOT IN ('','max','telegram','whatsapp') OR coalesce(length(_customer->>'messenger_contact'),0)>120 THEN RAISE EXCEPTION 'Проверьте мессенджер'; END IF; SELECT * INTO config FROM public.checkout_settings WHERE id=1; quote:=public.cart_quote(_items); IF (quote->>'shortfall')::numeric>0 THEN RAISE EXCEPTION 'Не достигнута минимальная сумма заказа'; END IF; IF NOT (CASE WHEN (quote->>'is_dealer')::boolean THEN config.wholesale_delivery ELSE config.retail_delivery END ? _delivery) THEN RAISE EXCEPTION 'Способ доставки недоступен'; END IF; IF (_buyer_type='person' AND (_payment<>'yookassa' OR NOT config.yookassa_enabled OR NOT config.test_mode)) OR (_buyer_type='organization' AND (_payment<>'invoice' OR NOT config.invoice_enabled)) THEN RAISE EXCEPTION 'Способ оплаты недоступен'; END IF; chosen_status:='awaiting_delivery'; INSERT INTO public.orders(user_id,customer,buyer_type,is_dealer,delivery_method,payment_method,total,weight_g,test_mode,consent,status) VALUES(auth.uid(),_customer,_buyer_type,(quote->>'is_dealer')::boolean,_delivery,_payment,(quote->>'total')::numeric,(quote->>'weight_g')::numeric,config.test_mode,true,chosen_status) RETURNING id,number INTO oid,ono; SELECT payment_tax_percent INTO tax FROM public.site_settings WHERE id=1; FOR item IN SELECT * FROM jsonb_array_elements(quote->'items') LOOP INSERT INTO public.order_items(order_id,variant_id,name,volume_ml,weight_g,sku,quantity,unit_price,gross_weight_g) VALUES(oid,(item->>'variant_id')::uuid,item->>'name',(item->>'volume_ml')::numeric,(item->>'weight_g')::numeric,item->>'sku',(item->>'quantity')::integer,(item->>'price')::numeric,(item->>'gross_weight_g')::numeric) RETURNING id INTO iid; SELECT cost_price INTO cost FROM public.variant_wholesale WHERE variant_id=(item->>'variant_id')::uuid; INSERT INTO public.order_item_private(item_id,cost_price,tax_percent,actual_margin_percent) VALUES(iid,cost,tax,CASE WHEN cost IS NULL OR (item->>'price')::numeric<=0 THEN NULL ELSE ((item->>'price')::numeric*(1-tax/100)-cost)/(item->>'price')::numeric*100 END); END LOOP; RETURN jsonb_build_object('id',oid,'number',ono,'status',chosen_status,'total',quote->'total','test_mode',config.test_mode); END $$;
REVOKE ALL ON FUNCTION public.place_order(jsonb,jsonb,text,text,text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.place_order(jsonb,jsonb,text,text,text) TO anon,authenticated;